diff --git a/xembed-sni-proxy/eisender.cpp b/xembed-sni-proxy/eisender.cpp
new file mode 100644
index 0000000000..49b49310b8
--- /dev/null
+++ b/xembed-sni-proxy/eisender.cpp
@@ -0,0 +1,154 @@
+/*
+    Sends emulated input through KWin's EIS server
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-or-later
+*/
+
+#include "eisender.h"
+
+#include <QDBusConnection>
+#include <QDBusMessage>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
+#include <QDBusUnixFileDescriptor>
+#include <QSocketNotifier>
+
+#include <libei.h>
+#include <linux/input-event-codes.h>
+#include <unistd.h>
+
+#include "debug.h"
+
+EiSender *EiSender::self()
+{
+    static EiSender *s_self = new EiSender;
+    return s_self;
+}
+
+EiSender::EiSender()
+{
+    connectToKWin();
+}
+
+EiSender::~EiSender()
+{
+    reset();
+}
+
+void EiSender::connectToKWin()
+{
+    constexpr int pointerCapability = 2;
+    auto message = QDBusMessage::createMethodCall(QStringLiteral("org.kde.KWin"),
+                                                  QStringLiteral("/org/kde/KWin/EIS/RemoteDesktop"),
+                                                  QStringLiteral("org.kde.KWin.EIS.RemoteDesktop"),
+                                                  QStringLiteral("connectToEIS"));
+    message << pointerCapability;
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(message), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        QDBusPendingReply<QDBusUnixFileDescriptor, int> reply = *watcher;
+        if (reply.isError()) {
+            qCDebug(SNIPROXY) << "Could not connect to KWin's EIS server, falling back to XTest" << reply.error();
+            return;
+        }
+        m_ei = ei_new_sender(nullptr);
+        ei_configure_name(m_ei, "xembedsniproxy");
+        if (ei_setup_backend_fd(m_ei, dup(reply.argumentAt<0>().fileDescriptor())) != 0) {
+            qCWarning(SNIPROXY) << "Could not set up libei";
+            reset();
+            return;
+        }
+        m_notifier = std::make_unique<QSocketNotifier>(ei_get_fd(m_ei), QSocketNotifier::Read);
+        connect(m_notifier.get(), &QSocketNotifier::activated, this, &EiSender::dispatch);
+        dispatch();
+    });
+}
+
+void EiSender::reset()
+{
+    if (m_notifier) {
+        m_notifier.release()->deleteLater();
+    }
+    m_device = ei_device_unref(m_device);
+    m_resumed = false;
+    m_ei = ei_unref(m_ei);
+}
+
+void EiSender::dispatch()
+{
+    ei_dispatch(m_ei);
+    while (ei_event *event = ei_get_event(m_ei)) {
+        ei_device *device = ei_event_get_device(event);
+        switch (ei_event_get_type(event)) {
+        case EI_EVENT_SEAT_ADDED:
+            ei_seat_bind_capabilities(ei_event_get_seat(event), EI_DEVICE_CAP_POINTER, EI_DEVICE_CAP_BUTTON, EI_DEVICE_CAP_SCROLL, nullptr);
+            break;
+        case EI_EVENT_DEVICE_ADDED:
+            if (!m_device && ei_device_has_capability(device, EI_DEVICE_CAP_BUTTON) && ei_device_has_capability(device, EI_DEVICE_CAP_SCROLL)) {
+                m_device = ei_device_ref(device);
+            }
+            break;
+        case EI_EVENT_DEVICE_RESUMED:
+            if (device == m_device) {
+                ei_device_start_emulating(m_device, 0);
+                m_resumed = true;
+            }
+            break;
+        case EI_EVENT_DEVICE_PAUSED:
+            if (device == m_device) {
+                m_resumed = false;
+            }
+            break;
+        case EI_EVENT_DEVICE_REMOVED:
+            if (device == m_device) {
+                m_device = ei_device_unref(m_device);
+                m_resumed = false;
+            }
+            break;
+        case EI_EVENT_DISCONNECT:
+            ei_event_unref(event);
+            reset();
+            return;
+        default:
+            break;
+        }
+        ei_event_unref(event);
+    }
+}
+
+bool EiSender::isReady() const
+{
+    return m_resumed;
+}
+
+void EiSender::sendButton(uint8_t button, bool pressed)
+{
+    // same mapping as Xwayland uses for XTest events
+    switch (button) {
+    case 1:
+        ei_device_button_button(m_device, BTN_LEFT, pressed);
+        break;
+    case 2:
+        ei_device_button_button(m_device, BTN_MIDDLE, pressed);
+        break;
+    case 3:
+        ei_device_button_button(m_device, BTN_RIGHT, pressed);
+        break;
+    case 4:
+    case 5:
+    case 6:
+    case 7:
+        if (pressed) {
+            const int delta = (button % 2 == 0) ? -120 : 120;
+            ei_device_scroll_discrete(m_device, button >= 6 ? delta : 0, button >= 6 ? 0 : delta);
+            ei_device_frame(m_device, ei_now(m_ei));
+        }
+        return;
+    default:
+        return;
+    }
+    ei_device_frame(m_device, ei_now(m_ei));
+}
+
+#include "moc_eisender.cpp"
