+/*
+    Sends emulated input through KWin's EIS server
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-or-later
+*/
+
+#pragma once
+
+#include <QObject>
+
+#include <cstdint>
+#include <memory>
+
+class QSocketNotifier;
+struct ei;
+struct ei_device;
+
+class EiSender : public QObject
+{
+    Q_OBJECT
+public:
+    static EiSender *self();
+    ~EiSender() override;
+
+    bool isReady() const;
+    void sendButton(uint8_t button, bool pressed);
+
+private:
+    EiSender();
+    void connectToKWin();
+    void dispatch();
+    void reset();
+
+    struct ei *m_ei = nullptr;
+    std::unique_ptr<QSocketNotifier> m_notifier;
+    ei_device *m_device = nullptr;
+    bool m_resumed = false;
+};
