 }

+void SNIProxy::sendInjectedButton(uint8_t mouseButton, bool pressed) const
+{
+#if HAVE_LIBEI
+    if (qgetenv("XDG_SESSION_TYPE") == QByteArrayLiteral("wayland") && EiSender::self()->isReady()) {
+        EiSender::self()->sendButton(mouseButton, pressed);
+        return;
+    }
+#endif
+    if (pressed) {
+        sendXTestPressed(m_x11Interface->display(), mouseButton);
+    } else {
+        sendXTestReleased(m_x11Interface->display(), mouseButton);
+    }
+}
+
 void SNIProxy::sendClick(uint8_t mouseButton, int x, int y)
 {
     // it's best not to look at this code
@@ -622,7 +646,7 @@ void SNIProxy::sendClick(uint8_t mouseButton, int x, int y)
         xcb_send_event(c, false, m_windowId, XCB_EVENT_MASK_BUTTON_PRESS, (char *)event);
         delete event;
     } else {
-        sendXTestPressed(m_x11Interface->display(), mouseButton);
+        sendInjectedButton(mouseButton, true);
     }

     // mouse up
@@ -645,7 +669,7 @@ void SNIProxy::sendClick(uint8_t mouseButton, int x, int y)
         xcb_send_event(c, false, m_windowId, XCB_EVENT_MASK_BUTTON_RELEASE, (char *)event);
         delete event;
     } else {
-        sendXTestReleased(m_x11Interface->display(), mouseButton);
+        sendInjectedButton(mouseButton, false);
     }

     if (m_injectMode == Direct) {
